#!/bin/bash
fail=0
d=$(mktemp -d); mkdir -p "$d/data/readings"
echo "s,2026-11-01T00:00:00Z,10" > "$d/data/readings/latest.csv"
out=$(cd "$d" && NOW=$(date -u -d 2026-11-01T10:00:00Z +%s) bash "$OLDPWD/ops/lag-alert.sh")
echo "$out" | grep -q '24' && { echo "mentions 24h: $out"; fail=1; }
echo "$out" | grep -q '上限 6 時間' || { echo "no 6h limit: $out"; fail=1; }
exit $fail

